-- Seed destinations. Safe to run again: existing slugs are updated.
-- Photographs are from Unsplash and are credited on the site.

insert into public.destinations
  (slug, name, country, country_code, region, best_season, best_start_month, best_end_month,
   summary, description, lat, lng, currency_code,
   image_url, image_alt, photographer, photographer_url, featured)
values
  ('positano', 'Positano', 'Italy', 'IT', 'riviera', 'summer', 4, 8, 'Pastel houses stacked above the sea, with lemon terraces and a pebble beach.', 'Positano climbs a steep hillside on the Amalfi Coast, with staircases and lanes running down to the water. Spend mornings on the beach, lunch under a lemon pergola and evenings on a terrace as the cliffs turn gold. Ferries along the coast run from May to October, and the sea is warmest from June to September.', 40.6281, 14.485, 'EUR', 'https://images.unsplash.com/photo-1782053492036-a235ddc5bb21', 'Pastel houses stacked up a steep hillside above the blue sea at Positano', 'Rafael Peier', 'https://unsplash.com/@rafaelpeier', true),
  ('santorini', 'Santorini', 'Greece', 'GR', 'riviera', 'summer', 4, 8, 'Whitewashed villages along the rim of a flooded volcano.', 'Santorini curves around a deep caldera, and its villages sit on the cliff edge with views across the water. Walk the path between Fira and Oia in the morning, before the heat and the day visitors arrive. May, June and September bring warm days with fewer people than July and August.', 36.3932, 25.4615, 'EUR', 'https://images.unsplash.com/photo-1652179326115-943d168c4cb2', 'Whitewashed buildings and blue church domes above the deep blue caldera at Oia, Santorini', 'Igor Ladigin', 'https://unsplash.com/@igorladigin', false),
  ('tuscany', 'Tuscany', 'Italy', 'IT', 'campagna', 'autumn', 8, 10, 'Cypress lanes, farmhouse tables and vineyards that turn copper.', 'Tuscany is a region of rolling hills, stone farmhouses and small hill towns that are easy to reach by car. September and October bring the grape harvest, and truffle markets open in the autumn. Book farmhouse stays early for the harvest weeks.', 43.3188, 11.3308, 'EUR', 'https://images.unsplash.com/photo-1788695903537-87519e6eb95b', 'Red and golden autumn vineyards rolling towards a hilltop village in Tuscany', 'Wolfgang Hasselmann', 'https://unsplash.com/@wolfgang_hasselmann', true),
  ('douro-valley', 'Douro Valley', 'Portugal', 'PT', 'campagna', 'autumn', 8, 9, 'Terraced vineyards above a slow river, and quintas that open their doors for the harvest.', 'The Douro Valley is Europe’s oldest demarcated wine region, with vineyards cut into the hillsides above the river. Travel by train from Porto or by boat, and stay at a quinta for a tasting. The grape harvest in September and October is the busiest and most memorable time to visit.', 41.162, -7.789, 'EUR', 'https://images.unsplash.com/photo-1792802143188-a117106e7ab4', 'Terraced vineyards climbing the hillsides above the Douro River in Portugal''s Douro Valley', 'Vincent Yap', 'https://unsplash.com/@chonky_films', false),
  ('zermatt', 'Zermatt', 'Switzerland', 'CH', 'alpine', 'winter', 11, 2, 'A car-free alpine village below the Matterhorn, with snow from December to March.', 'Zermatt has no cars in its centre, so the village is quiet, and the Matterhorn rises above the rooftops. Cable cars reach high terraces for skiing and for walks with views across the glaciers. The lifts open from mid December, and snow is most reliable from January to March.', 46.0207, 7.7491, 'CHF', 'https://images.unsplash.com/photo-1595090947130-23c5948a2993', 'The snow-covered Matterhorn catching the last orange light above Zermatt', 'Andrews Art', 'https://unsplash.com/@podders', true),
  ('dolomites', 'Dolomites', 'Italy', 'IT', 'alpine', 'summer', 5, 8, 'Pale limestone peaks above green meadows, with mountain huts that serve lunch.', 'The Dolomites are a range of pale limestone peaks in northern Italy, with marked trails and mountain huts at every level. Hike from hut to hut in summer, or ride a cable car to a high meadow and walk down. Most mountain huts are open from June to September, so plan for those months.', 46.5405, 12.1357, 'EUR', 'https://images.unsplash.com/photo-1534106474077-f9e9c6f5a47c', 'Jagged Sassolungo and Sasso Piatto peaks rising above green meadows and pine forest in the Dolomites', 'Michiel Ronde', 'https://unsplash.com/@chielr', false),
  ('lofoten', 'Lofoten', 'Norway', 'NO', 'nordic', 'summer', 5, 7, 'Red fishing cabins at the foot of steep peaks, and light that lasts through the night.', 'Lofoten is an island chain above the Arctic Circle, with fishing villages tucked between the sea and sharp mountains. From late May to mid July the sun does not set, so there is time for a hike after dinner. Stay in a rorbu, a fishermen’s cabin, and book it months ahead for July.', 68.2, 14.56, 'NOK', 'https://images.unsplash.com/photo-1663428520845-056989f8a664', 'Red fishing cabins on the rocky shore below a steep granite peak at Hamnoy, Lofoten', 'Benoît Deschasaux', 'https://unsplash.com/@benowa', true),
  ('lapland', 'Lapland', 'Finland', 'FI', 'nordic', 'winter', 11, 2, 'Snowy forest, quiet lakes and a good chance of the northern lights.', 'Lapland has deep snow from December, huskies and reindeer on the trails, and long dark evenings that suit the northern lights. Stay in a lakeside cabin with a sauna and plan outdoor days around the short daylight. The aurora is most often seen from September to March on clear nights.', 66.5039, 25.7294, 'EUR', 'https://images.unsplash.com/photo-1674507059162-b55a0626203c', 'Snow-laden spruce trees under a pink twilight sky in Finnish Lapland', 'Harri P', 'https://unsplash.com/@haraldip', false),
  ('algarve', 'Algarve', 'Portugal', 'PT', 'atlantic', 'spring', 3, 5, 'Golden cliffs, sea arches and warm water, before the summer crowds.', 'The Algarve coast is a run of golden cliffs, rock arches and small coves that are reached by boat or by steps cut into the stone. April to June brings mild days, wildflowers on the clifftop paths and quiet beaches. The Atlantic is cool, so many guests swim from late May.', 37.0179, -7.9304, 'EUR', 'https://images.unsplash.com/photo-1764077299795-ff605e3f7301', 'Golden sandstone sea cliffs and a rock arch above turquoise water on the Algarve coast', 'Jeffrey Eisen', 'https://unsplash.com/@jeisen', false),
  ('keukenhof', 'Keukenhof', 'Netherlands', 'NL', 'atlantic', 'spring', 3, 4, 'Tulip fields in long coloured rows, a short drive from the North Sea dunes.', 'Keukenhof sits in the bulb fields near Lisse, where tulips flower in long coloured rows. The gardens open from mid March to mid May, and the fields are at their best in mid April. Hire a bicycle in Lisse to ride between the fields, and go early on weekdays to avoid the queues.', 52.2697, 4.5461, 'EUR', 'https://images.unsplash.com/photo-1599725396833-6b96520b550e', 'A ribbon of tulips and blue grape hyacinths flowing across the lawns at Keukenhof, Lisse', 'Boudewijn Huysmans', 'https://unsplash.com/@boudewijn_huysmans', true),
  ('prague', 'Prague', 'Czechia', 'CZ', 'capitals', 'spring', 3, 5, 'Red rooftops, a medieval bridge and café courtyards that open in spring.', 'Prague’s old town is compact and easy to walk, with the castle above the river and cafés in the courtyards. Cross the Charles Bridge at sunrise, before the crowds, and spend afternoons in the riverside gardens. Spring brings blossom in the parks and terraces that reopen after winter.', 50.0755, 14.4378, 'CZK', 'https://images.unsplash.com/photo-1600623471616-8c1966c91ff6', 'Charles Bridge and Prague Castle glowing over the Vltava River at golden hour in Prague', 'William Zhang', 'https://unsplash.com/@ceye2eye', true),
  ('vienna', 'Vienna', 'Austria', 'AT', 'capitals', 'autumn', 8, 10, 'Grand cafés, opera nights and a city that settles back into itself in autumn.', 'Vienna is a city of grand cafés, concert halls and palace gardens, and it is calm after the summer visitors leave. Spend an afternoon over a coffee, then a night at the opera or a concert. September and October bring warm days and new wine at the vineyard taverns on the edge of town.', 48.2082, 16.3738, 'EUR', 'https://images.unsplash.com/photo-1516550893923-42d28e5677af', 'St. Stephen''s Cathedral spire rising above Vienna''s rooftops at dusk', 'Jacek Dylag', 'https://unsplash.com/@dylu', false),
  ('paris', 'Paris', 'France', 'FR', 'capitals', 'winter', 11, 1, 'Lamplit streets, warm cafés and quiet museums in the cold months.', 'Paris in winter is quieter, with shorter queues at the museums and warm cafés on every corner. Walk the river at dusk, when the lamps come on, and visit the Christmas markets in December. Book restaurants ahead for the weeks around the holidays.', 48.8566, 2.3522, 'EUR', 'https://images.unsplash.com/photo-1587172653333-4d85727afdc3', 'Paris rooftops and boulevards stretching towards the Eiffel Tower under a pink winter sunset', 'Bethan James', 'https://unsplash.com/@bethanjames', false)
on conflict (slug) do update set
  name = excluded.name,
  country = excluded.country,
  country_code = excluded.country_code,
  region = excluded.region,
  best_season = excluded.best_season,
  best_start_month = excluded.best_start_month,
  best_end_month = excluded.best_end_month,
  summary = excluded.summary,
  description = excluded.description,
  lat = excluded.lat,
  lng = excluded.lng,
  currency_code = excluded.currency_code,
  image_url = excluded.image_url,
  image_alt = excluded.image_alt,
  photographer = excluded.photographer,
  photographer_url = excluded.photographer_url,
  featured = excluded.featured;
